parameters.jsCode:
const body = $('Webhook').item.json.body;
const nombre = body.nombre || "";
const phone = body.telefono || body.phone || body.data?.key?.remoteJid?.split('@')[0] || "unknown";
const incomingMessage = body.message || body.data?.message?.conversation || body.data?.message?.extendedTextMessage?.text || "";

// Formatear el historial de chat devuelto por la Evolution API (si hay alguno)
let chatHistoryText = "";
try {
  const messages = input.all(); // Salida del nodo Buscar Historial
  if (messages && messages.length > 0) {
    // Invertir el orden para leer cronológicamente
    const sorted = messages.map(m => m.json).filter(m => m && m.message).reverse();
    chatHistoryText = sorted.map(m => {
      const sender = m.key?.fromMe ? "Asistente" : "Cliente";
      const text = m.message.conversation || m.message.extendedTextMessage?.text || "";
      return `- ${sender}: ${text}`;
    }).join("\n");
  }
} catch (e) {
  console.log("No se pudo leer el historial:", e);
}

let promptText = "";
if (nombre) {
  promptText = `NUEVO REGISTRO DESDE LA LANDING - Nombre: ${nombre}, Teléfono: ${phone}, Mensaje: ${body.mensaje || ''}. Inicia la conversación de WhatsApp saludándolo por su nombre de forma muy natural y pregúntale en qué consiste su proyecto.`;
} else {
  promptText = incomingMessage;
}

return {
  json: {
    phone,
    promptText,
    chatHistoryText,
    systemInstruction: "Eres Sofía, asistente comercial automatizada de Laibe Studio AI. Ayudas a empresas de reformas integrales, constructoras y autónomos del sector a digitalizar y automatizar sus procesos. Mantén tus mensajes en un máximo de 2 líneas de texto, con tono profesional, directo y empático. Realiza solo una pregunta por mensaje. Criterios de cualificación: 1. Confirmar que son empresa de reformas/construcción. 2. Preguntar mayor cuello de botella actual (leads lentos, presupuestos manuales, sin CRM). 3. Mencionar que una solución arranca en 1.000€-1.500€ y confirmar si están abiertos a invertir. Si califica, ofréceles agendar sesión de diagnóstico gratuito en laibestudioai.com/#agenda-seccion."
  }
};

